\label{lemma: deltas}
		For $u_-,u_+\geqslant0$ with $u_-+u_+>0$ and $\beta\geqslant0$,
		\begin{align}
			\delta_-(u_-,u_+,\beta)
			&=
			\frac{W^{(\beta)}(u_+)}
			{W^{(\beta)}(u_-+u_+)},
			\label{eq: delta_min}\\
			\delta_+(u_-,u_+,\beta)
			&=
			Z^{(\beta)}(u_+)
			-
			Z^{(\beta)}(u_-+u_+)
			\frac{W^{(\beta)}(u_+)}
			{W^{(\beta)}(u_-+u_+)},
			\label{eq: delta_plus}
		\end{align}

\label{lemma: Levy exit probabilities}
		For $u_-, u_+\geqslant0$ and $\beta\geqslant0$,
		\begin{align}
			\mathbb{P}\bigl(\sigma(u_-)\leqslant T_\beta\bigr)
			&=
			e^{-\psi(\beta)u_-}, \label{eq: sigma before killing}\\
			\mathbb{P}\bigl(\tau(u_+)\leqslant T_\beta\bigr)
			&=
			Z^{(\beta)}(u_+)
			-
			\frac{\beta}{\psi(\beta)}W^{(\beta)}(u_+).
			\label{eq: tau before killing}
		\end{align}

\label{lemma: eta}
		For $u_+\geqslant0$ and $\alpha,\beta\geqslant0$,
		\begin{equation}\label{eq: eta}
			\eta(u_+,\alpha,\beta)
			= 
			(\varphi(\alpha)-\beta)
			\int_{u_+}^\infty e^{-\alpha (y-u_+)}W^{(\beta)}(y)\,\mathrm{d}y
			+
			\frac{\varphi(\alpha)-\beta}
			{\psi(\beta)-\alpha}
			W^{(\beta)}(u_+).
		\end{equation}

\label{lemma: ruin prob v=0}
		For $u>0$ and $\beta\geqslant0$
		\begin{equation}\label{eq: ruin prob v=0}
			p(u,0,\beta) = \frac{\int_0^{u} h_1(0, y, \beta)\,\delta_{2,+}(y, u-y, \beta)\,\mathrm{d}y + \int_{u}^\infty h_1(0, y, \beta)\,\mathrm{d}y}{1 - \int_0^{u} h_1(0, y, \beta)\,\delta_{2,-}(y, u-y,\beta)\,\mathrm{d}y}.
		\end{equation}

\label{lemma: ruin prob v>0}
		For $u>v>0$ and $\beta\geqslant0$
		\begin{align}\label{eq: ruin prob v>0}
			\notag p(u,v,\beta) &= \int_{u-v}^\infty h_1(v,y,\beta) \,\mathrm{d}y + \int_{0}^{u-v} \delta_{2,+}(y, u-v-y, \beta) h_1(v,y,\beta) \,\mathrm{d}y\\
			&\:\:\:\:\:\:\:+ \int_{0}^{u-v} \delta_{2,-}(y, u-v-y, \beta) h_1(v,y,\beta) \,\mathrm{d}y \times p(u-v, 0, \beta)
		\end{align}
		with $p(u-v, 0, \beta)$ as given in \eqref{eq: ruin prob v=0}.

\label{lemma: ruin prob v<0}
		For $u \geqslant 0 > v$ and $\beta \geqslant 0$
		\begin{equation}\label{eq: ruin prob v<0}
			p(u,v,\beta) = \delta_{2,+}(-v,u,\beta) + \delta_{2,-}(-v, u, \beta) \times p(u-v,0,\beta)
		\end{equation}
		with $p(u-v,0,\beta)$ as given in \eqref{eq: ruin prob v=0}.

\label{rem: all-time ruin prob}
		{\em When $\mathbb{E}(Y_1(1)) > 0$ the all-time ruin probability is always equal to one. Indeed, since $\mathbb{P}(\tau_1(0) < \infty) = 1$ in this case, we have 
			\begin{align*}
				\int_0^{u} &h_1(0, y, 0)\,\delta_{2,+}(y, u-y, 0)\,\mathrm{d}y + \int_{u}^\infty h_1(0, y, 0)\,\mathrm{d}y \\
				=&\: \int_0^{u} h_1(0, y, 0)\,\left(1-\delta_{2,-}(y, u-y, 0)\right)\,\mathrm{d}y + \int_{u}^\infty h_1(0, y, 0)\,\mathrm{d}y \\
				=&\: 1 - \int_0^{u} h_1(0, y, 0)\,\delta_{2,-}(y, u-y, 0)\,\mathrm{d}y,
			\end{align*}
			so that $p(u,0,0) = 1$ by Lemma \ref{lemma: ruin prob v=0}. It is easily verified from Lemma \ref{lemma: ruin prob v>0} and Lemma \ref{lemma: ruin prob v<0} that $p(u,v,0) = 1$ for any $v < u$.}

\label{lemma: delta_star}
		For $x\in[0,v]$, $i=1,2$, $\alpha\geqslant0$, and $\beta>0$,
		\begin{equation}\label{eq: delta_star decomp}
			\delta_{i,\star}(x,v-x)
			=
			\left(
			e^{-\alpha x}
			-\delta_{i,-}(x)
			-e^{-\alpha v}\eta_i(v-x,\alpha,\beta)
			+e^{-\alpha v}\delta_{i,-}(x)\eta_i(v,\alpha,\beta)
			\right)
			\frac{\beta}{\beta-\varphi_i(\alpha)}.
		\end{equation}

For $x\in[0,v]$, $i=1,2$, $\alpha\geqslant0$, and $\beta>0$,
		\begin{equation}\label{eq: delta_star scale func}
			\delta_{i,\star}(x,v-x)
			=
			\beta
			\frac{W_i^{(\beta)}(v-x)}
			{W_i^{(\beta)}(v)}
			\int_0^v e^{-\alpha y}W_i^{(\beta)}(y)\,\mathrm{d}y
			-
			\beta e^{-\alpha x}
			\int_0^{v-x}e^{-\alpha y}W_i^{(\beta)}(y)\,\mathrm{d}y.
		\end{equation}

\label{prop: chi(x)}
		Let $\beta>0$. For $x\in(v,\infty)$
		\begin{equation}\label{eq: chi(x) for x > v}
			\chi(x)
			=
			\frac{\beta}{\beta-\varphi_2(\alpha)}
			\left(
			e^{-\alpha x}
			-e^{-\alpha v}e^{-\psi_2(\beta)(x-v)}
			\right)
			+
			e^{-\psi_2(\beta)(x-v)}\chi(v),
		\end{equation}
		and for $x\in[0,v]$
		\begin{align}
			\chi(x)
			&=
			\delta_{1,-}(x,v-x)\chi(0)
			+\tilde{\eta}_1(x,v-x,\psi_2(\beta),\beta)\chi(v)
			\notag\\
			&\quad
			+\frac{\beta}{\beta-\varphi_2(\alpha)}
			e^{-\alpha v}
			\left(
			\tilde{\eta}_1(x,v-x,\alpha,\beta)
			-
			\tilde{\eta}_1(x,v-x,\psi_2(\beta),\beta)
			\right)
			+\delta_{1,\star}(x,v-x).
			\label{eq: chi(x) for x < v}
		\end{align}

\label{remark: duality}
		{\em
			In general, the well-known duality between ruin probabilities and workload distributions does not directly apply to the model considered here. An exception occurs when $Y_1$ and $Y_2$ differ only in their drift parameters, i.e., when $\lambda_1=\lambda_2$, $B_1$ and $B_2$ are identically distributed, and $r_1\neq r_2$. In this case, we can express $\chi(0)$ in terms of a ruin probability.

			To see this, for $z\geqslant0$ define $Y_{z-v}^*$ as the cumulative claim process of Section \ref{sec: Cramer-Lundberg model} with threshold $v^*=z-v$, driven by $Y_2$ below $v^*$ and by $Y_1$ above $v^*$. Let $R^*(t)=z-Y_{z-v}^*(t)$. By the duality argument of \cite[\S III.2, Theorem 2.1]{AA}, the risk process obtained from the workload process has the same distribution as $R^*$. Consequently,
			\begin{equation}\label{eq: duality}
				{\mathbb{P}\left(V_v(T_\beta)>z\,\middle|\,V_v(0)=0\right)}
				=
				\mathbb{P}\left(\bar{Y}_{z-v}^*(T_\beta)>z\right).
			\end{equation}
			Taking the Laplace transform with respect to $z$ therefore yields
			\begin{equation*}
				\chi(0)
				=
				1-\alpha\int_0^\infty
				e^{-\alpha z}
				\mathbb{P}\left(\bar{Y}_{z-v}^*(T_\beta)>z\right)
				\,\mathrm{d}z,
			\end{equation*}
			where the ruin probability on the right-hand side is given by the results of Section \ref{sec: Cramer-Lundberg model}.
			\hfill$\Diamond$}

\label{lemma: relations psi_2}
		Under Assumption \ref{assump: stability} we have (i)~$\psi_2(0) = 0$,
		and (ii)~$\varphi_2'(0)\psi_2'(0) = 1$.

\label{theorem: stationary LST workload}
		For $\alpha\geqslant0$,
		\begin{equation}\label{eq: stationary LST workload}
			\mathbb{E}e^{-\alpha V_v}
			=
			\frac{f(v,\alpha)}{f(v,0)},
		\end{equation}
		where
		\begin{align*}
			f(v,\alpha)
			&:=
			\frac{1}{\lambda_1}
			+\frac{1-\mathbb{E}(e^{-\alpha B_1})}
			{\varphi_2(\alpha)}
			+\left(
			1-\frac{\varphi_1(\alpha)}
			{\varphi_2(\alpha)}
			\right)
			\int_0^v e^{-\alpha y}W_1^{(0)}(y)
			\left(
			1-
			\int_0^{v-y}e^{-\alpha x}
			\mathbb{P}(B_1\in\mathrm{d}x)
			\right)\mathrm{d}y,
			\\
			f(v,0) &\equiv \lim_{\alpha\downarrow0} f(v,\alpha) 
			=
			\frac{1}{\lambda_1}
			+\psi_2'(0)\,\mathbb{E}(B_1)
			+\left(
			1-\varphi_1'(0)\,\psi_2'(0)
			\right)
			\int_0^v
			W_1^{(0)}(y)
			\mathbb{P}(B_1>v-y)\,\mathrm{d}y.
		\end{align*}

{\em 
			In the special case
			\[
			\varphi_i(\alpha)
			= g_i\alpha-\lambda_i\frac{\alpha}{\mu_i+\alpha},
			\qquad i=1,2,
			\]
			the model corresponds to an M/M/1 queue with arrival rate
			$\lambda_i$, service rate $\mu_i$, and service speed $r_i=-g_i$ in
			mode $i$. In this case, Proposition~\ref{theorem: stationary LST workload}
			gives
			\[
			f(v,\alpha)
			=
			\frac{1}{\lambda_1}
			+\frac{1}{g_1\alpha+g_1\mu_1-\lambda_1}
			+e^{-(\alpha+\mu_1-\lambda_1/g_1)v}
			\left[
			\frac{\mu_2+\alpha}{\mu_1+\alpha}
			\frac{1}{g_2\alpha+g_2\mu_2-\lambda_2}
			-\frac{1}{g_1\alpha+g_1\mu_1-\lambda_1}
			\right],
			\]
			with $f(v,0)$ given by the same expression at $\alpha=0$.
			Inverting the LST shows that $V_v$ has an atom of size
			$1/(\lambda_1 f(v,0))$ at zero and density, with $\nu_i:=\mu_i-\lambda_i/g_i$ for $i=1,2$,
			\[
			\frac{1}{f(v,0)}
			\left[
			\frac{1}{g_1}e^{-\nu_1 x}
			+e^{-\nu_1 v}
			\left(
			U_1e^{-\mu_1(x-v)}
			+\frac{U_2}{g_2}e^{-\nu_2(x-v)}
			-\frac{1}{g_1}e^{-\nu_1(x-v)}
			\right)\mathbf{1}_{\{x>v\}}
			\right],
			\]
			where
			\[
			U_1:=\frac{\mu_2-\mu_1}{g_2(\mu_2-\mu_1)-\lambda_2},
			\qquad
			U_2:=-\frac{\lambda_2}{g_2(\mu_2-\mu_1)-\lambda_2}.
			\]
			For $x>v$, the first and last terms in this density cancel. \hfill$\Diamond$}

\label{prop: chi(x) capacity}
		Let $\beta>0$.  For $x\in(v,K]$
		\begin{equation}\label{eq: chi(x) capacity v < x < K}
			\widehat\chi(x) = \delta_{2,-}(x-v, K-x, \beta)\widehat\chi(v) + \delta_{2,+}(x-v, K-x, \beta)\widehat\chi(K) + \delta_{2,\star}(x-v, K-x, \beta),
		\end{equation}
		and for  $x\in[0,v]$
		\begin{align}\label{eq: chi(x) capacity 0 < x < v}
			\notag\widehat\chi(x) =&\: \delta_{1,-}(x, v-x, \beta)\widehat\chi(0) + \int_0^{K-v} \tilde{h}_1(x,v-x,y,\beta)\delta_{2,-}(y,(K-v)-y,\beta)\,\mathrm{d}y\,\widehat\chi(v) \:+\\
			\notag&\: \int_0^{K-v} \tilde{h}_1(x,v-x,y,\beta)\delta_{2,+}(y,(K-v)-y,\beta)\,\mathrm{d}y\,\widehat\chi(K) \:+\\
			\notag&\: \int_{K-v}^\infty \tilde{h}_1(x,v-x,y,\beta)\,\mathrm{d}y\,\widehat\chi(K) \:+\\
			&\: \int_0^{K-v} \tilde{h}_1(x,v-x,y,\beta)\delta_{2,\star}(y,(K-v)-y,\beta)\,\mathrm{d}y + \delta_{1,\star}(x, v-x, \beta).
		\end{align}

\label{lemma: expansion2 chi(0) chi(v) chi(K)}
		For $\beta>0$, 
		\begin{equation}
			\widehat{\boldsymbol \chi}
			= 
			(\boldsymbol{I} - \widehat{\boldsymbol P})^{-1}
			\widehat{\boldsymbol{b}}.
		\end{equation}

The second and third entries of $(\boldsymbol{I}-\widehat{\boldsymbol P})\widehat{\boldsymbol\chi}=\widehat{\boldsymbol b}$ follow directly from Proposition~\ref{prop: chi(x) capacity}, with $x=v$ and $x=K$, respectively.
		For the first entry, corresponding to a system that is initially empty, we again condition on the first event. In this case this is either killing or an arrival from $Y_1$. In the case of an arrival, the job 
		size can either be less than or equal to $v$, greater than $v$ and less than or equal to $K$, or greater than $K$. This gives
		\begin{align*}
			\widehat\chi(0) &= \frac{\beta}{\lambda_1 + \beta} + \frac{\lambda_1}{\lambda_1+\beta}\int_0^\infty \mathbb{P}\left(B_1\in\mathrm{d}x\right)\widehat\chi(x),
		\end{align*}
		where
		\begin{align*}
			\int_0^\infty \mathbb{P}\left(B_1\in\mathrm{d}x\right)\widehat\chi(x)&= \int_{[0,v]} \mathbb{P}\left(B_1\in\mathrm{d}x\right)\widehat\chi(x) + \int_{(v,K]} \mathbb{P}\left(B_1\in\mathrm{d}x\right)\widehat\chi(x) + \int_{(K,\infty)} \mathbb{P}\left(B_1\in\mathrm{d}x\right)\widehat\chi(K).
		\end{align*}
		Substituting the decompositions for $\chi(x)$ as given in Proposition \ref{prop: chi(x) capacity} under their respective integrals gives the first entry of $(\boldsymbol{I} - \widehat{\boldsymbol P})\widehat{\boldsymbol \chi}
		= 
		\widehat{\boldsymbol{b}}$.
		In order to show that $\boldsymbol{I} - \widehat{\boldsymbol P}$ is invertible, it suffices to observe that the row-sums of $\widehat{\boldsymbol P}$ are less than one entry-wise.

Let $0\leqslant u \leqslant v$ and $\beta > 0$.  For $x=0$
		\begin{align}\label{eq: p^V for 0<=u<=v and x=0}
			p^V(u,v,0,\beta) = \frac{\int_{(u,\infty)} \mathbb{P}(B_1\in\mathrm{d}y) + \int_{[0,u]} \mathbb{P}(B_1\in\mathrm{d}y)\,\delta_{1,+}(y,u-y,\beta)}{\displaystyle{{\frac{\lambda_1 + \beta}{\lambda_1}}} - \int_{[0,u]} \mathbb{P}(B_1\in\mathrm{d}y)\,\delta_{1,-}(y,u-y,\beta)},
		\end{align}
		and for $0<x\leqslant u$
		\begin{align}\label{eq: p^V for 0<=u<=v and 0<x<=v}
			p^V(u,v,x,\beta) = \delta_{1,+}(x,u-x,\beta) + \delta_{1,-}(x,u-x,\beta)p^V(u,v,0,\beta).
		\end{align}

Let $ u > v$ and $\beta > 0$. For $x\in (u,v)$
		\begin{align}\label{eq: p^V for u>v and v<x<u}
			p^V(u,v,x,\beta) = \delta_{2,+}(x-v, u-x, \beta) + \delta_{2,-}(x-v, u-x, \beta)p^V(u,v,v,\beta),
		\end{align}
		and for $x\in(0, v]$
		\begin{align}
			\notag p^V(u,v,x,\beta) &= \int_{u-v}^\infty \tilde{h}_1(x,v-x,y,\beta)\,\mathrm{d}y + \int_0^{u-v} \tilde{h}_1(x,v-x,y,\beta)\delta_{2,+}(y,u-v-y,\beta)\,\mathrm{d}y \\
			\notag&\:\:\:\:\:+\int_0^{u-v} \tilde{h}_1(x,v-x,y,\beta)\delta_{2,-}(y,u-v-y,\beta)\,\mathrm{d}y\cdot p^V(u,v,v,\beta) \\
			&\:\:\:\:\:+\delta_{1,-}(x,v-x,\beta)p^V(u,v,0,\beta). \label{eq: p^V for u>v and 0<x<=v}
		\end{align}

\label{lemma:B invertible}
		If $\alpha_1,\ldots,\alpha_d$ are distinct and none is an eigenvalue of
		$\boldsymbol S$, then $\boldsymbol B$ is nonsingular.

\label{lemma: q vs Bc}
		For $\beta > 0$, 
		\begin{equation}\label{eq: q vs Bc}
			\boldsymbol{q}(\alpha) = \boldsymbol{B}^\top\boldsymbol{\mathfrak{C}}(\alpha).
		\end{equation}

\label{lemma: relation B vs B_j}
		For $\beta>0$,
		\begin{equation}\label{eq: relation B vs B_j}
			\boldsymbol{B}^\top\boldsymbol{c}
			= -c_{d+1}\boldsymbol{\mathscr{B}}(\alpha_{d+1}).
		\end{equation}

Let $\pi^*_1, \dots, \pi^*_{n^*}$ denote the roots of $p(\alpha)$ and
		let $d^*_1, \dots,d^*_{n^*}$ denote their multiplicities respectively.
		Then, for some constants $c^*_{i\ell j}$, we write
		$\mathscr{B}_j(\alpha)$ in terms of its partial fraction decomposition
		as follows:
		\begin{equation}\label{eq: partial frac decomp B_j(alpha)}
			\mathscr{B}_j(\alpha) = \frac{q_j(\alpha)}{p(\alpha)}
			= \sum_{i=1}^{n^*} \sum_{\ell = 1}^{d^*_i}
			\frac{c^*_{i\ell j}}{(\alpha - \pi^*_i)^\ell}.
		\end{equation}
		Furthermore, since the leading coefficient of $p(\alpha)$ is $1$, we
		can write
		\begin{equation*}
			p(\alpha) = \prod_{i=1}^{n^*}(\alpha - \pi^*_i)^{d^*_i},
		\end{equation*}
		from which it follows that, for $i=1,\dots,n^*$,
		\begin{equation}\label{eq: all deriv p zer0}
			p(\pi^*_i) = p^{(1)}(\pi_i^*) = \dots =
			p^{(d_i-1)}(\pi^*_i) = 0.
		\end{equation}
		Hence, for each $i=1,\dots,n^*$, the first $d_i^*-1$ derivatives of
		$p(\alpha)/\tilde{q}(\alpha)$ also vanish at $\alpha=\pi_i^*$. Using
		the partial fraction decomposition in
		\eqref{eq: partial frac decomp p / tilde q}, we obtain, for
		$\ell=0,\dots,d_i^*-1$,
		\begin{equation}\label{eq: all deriv p / tilde q zero}
			0 =
			\frac{\partial^\ell}{\partial \alpha^\ell}
			\frac{p(\alpha)}{\tilde{q}(\alpha)}
			\Bigg|_{\alpha = \pi^*_i}
			= \sum_{k=1}^{d+1}
			(-1)^\ell \ell!
			\frac{c_k}{(\pi^*_i - \alpha_k)^{\ell+1}}.
		\end{equation}
		Finally, using \eqref{eq: partial frac decomp B_j(alpha)}, we have
		\begin{align*}
			\sum_{k=1}^{d+1}c_k \mathscr{B}_j(\alpha_k)
			&= \sum_{k=1}^{d+1}c_k
			\sum_{i=1}^{n^*}\sum_{\ell=1}^{d^*_i}
			\frac{c^*_{i\ell j}}{(\alpha_k - \pi^*_i)^\ell} \\
			&= \sum_{i=1}^{n^*}\sum_{\ell=1}^{d^*_i}
			\frac{c^*_{i\ell j}}{(-1)^{\ell-1}(\ell-1)!}
			\sum_{k=1}^{d+1}
			(-1)^{\ell-1}(\ell-1)!
			\frac{c_k}{(\alpha_k - \pi^*_i)^\ell}
			= 0,
		\end{align*}
		by \eqref{eq: all deriv p / tilde q zero}. Thus, for all $j\in[d]$,
		\begin{equation*}
			\sum_{k=1}^{d}c_k\mathscr{B}_j(\alpha_k)
			= -c_{d+1}\mathscr{B}_j(\alpha_{d+1}),
		\end{equation*}
		which is equivalent to \eqref{eq: relation B vs B_j}.

\label{lemma: relation M B_inv}
		For $u_-,u_+\geqslant0$ with $u_-+u_+ >0$, and $\beta > 0$,
		\begin{equation}\label{eq: MB_inv}
			\boldsymbol{M}\boldsymbol{B}^{-1}
			\left(\boldsymbol{\theta}(u_+)
			- \delta_-(u_-,u_+,\beta)\boldsymbol{\theta}(u_-+u_+)\right)
			= e^{\alpha_{d+1}(u_-+u_+)}\boldsymbol{\theta}(u_+)
			- e^{\alpha_{d+1}u_+}\boldsymbol{\theta}(u_-+u_+).
		\end{equation}

Starting with
		$\boldsymbol{M}\boldsymbol{B}^{-1}
		=e^{\alpha_{d+1}(u_-+u_+)}\boldsymbol{I}
		-\tilde{\boldsymbol{B}}\boldsymbol{B}^{-1}$,
		we obtain for the left-hand side of \eqref{eq: MB_inv}
		\begin{align}
			\notag e^{\alpha_{d+1}(u_-+u_+)}
			&\boldsymbol{\theta}(u_+)
			-e^{\alpha_{d+1}(u_-+u_+)}
			\delta_-(u_-,u_+,\beta)\boldsymbol{\theta}(u_-+u_+) \\
			&-\tilde{\boldsymbol{B}}\boldsymbol{B}^{-1}\boldsymbol{\theta}(u_+)
			+\delta_-(u_-,u_+,\beta)
			\tilde{\boldsymbol{B}}\boldsymbol{B}^{-1}\boldsymbol{\theta}(u_-+u_+).
			\label{eq: temp MB_inv}
		\end{align}
		Furthermore, by Lemma~\ref{lemma: relation B vs B_j},
		\begin{equation*}
			\tilde{\boldsymbol{B}}\boldsymbol{B}^{-1}
			=\boldsymbol{\theta}(u_-+u_+)
			\left(\boldsymbol{\mathscr{B}}(\alpha_{d+1})^\top\boldsymbol{B}^{-1}\right)
			=-\frac{1}{c_{d+1}}
			\boldsymbol{\theta}(u_-+u_+)\boldsymbol{c}^\top.
		\end{equation*}
		Hence \eqref{eq: temp MB_inv} can be written as
		\begin{align}
			\notag e^{\alpha_{d+1}(u_-+u_+)}
			&\boldsymbol{\theta}(u_+)
			-e^{\alpha_{d+1}(u_-+u_+)}
			\delta_-(u_-,u_+,\beta)\boldsymbol{\theta}(u_-+u_+) \\
			&\:\:\:\:\:
			+\frac{1}{c_{d+1}}
			\left(\boldsymbol{c}^\top\boldsymbol{\theta}(u_+)\right)
			\boldsymbol{\theta}(u_-+u_+)
			-\frac{1}{c_{d+1}}
			\delta_-(u_-,u_+,\beta)
			\left(\boldsymbol{c}^\top\boldsymbol{\theta}(u_-+u_+)\right)
			\boldsymbol{\theta}(u_-+u_+).
		\end{align}
		This can be rewritten as
		\begin{align*}
			&e^{\alpha_{d+1}(u_-+u_+)}\boldsymbol{\theta}(u_+)
			-\frac{1}{c_{d+1}}
			\left(
			c_{d+1}e^{\alpha_{d+1}(u_-+u_+)}
			+\boldsymbol{c}^\top\boldsymbol{\theta}(u_-+u_+)
			\right)
			\delta_-(u_-,u_+,\beta)\boldsymbol{\theta}(u_-+u_+)\\
			&\quad
			+\frac{1}{c_{d+1}}
			\left(\boldsymbol{c}^\top\boldsymbol{\theta}(u_+)\right)
			\boldsymbol{\theta}(u_-+u_+).
		\end{align*}
		With the expression for $\delta_-(u_-,u_+,\beta)$ in
		\eqref{eq: delta_min scale func}, this simplifies to
		\begin{align*}
			&e^{\alpha_{d+1}(u_-+u_+)}\boldsymbol{\theta}(u_+)
			-\frac{1}{c_{d+1}}
			\left(\sum_{k=1}^{d+1}c_ke^{\alpha_k u_+}\right)
			\boldsymbol{\theta}(u_-+u_+)
			+\frac{1}{c_{d+1}}
			\left(\boldsymbol{c}^\top\boldsymbol{\theta}(u_+)\right)
			\boldsymbol{\theta}(u_-+u_+),
		\end{align*}
		which equals the right-hand side of \eqref{eq: MB_inv}.

\label{lemma: proof LSTs same}
		For $v>0$,
		\begin{equation}\label{eq: proof LSTs same}
			\int_0^v e^{-\alpha x}\mathrm{d} W^{(0)}_1(x) = \frac{\lambda_1}{-r_1} \int_0^v e^{-\alpha y} W^{(0)}_1(y) \left(1- \int_0^{v-y} e^{-\alpha x} \mathbb{P}(B_1\in\mathrm{d}x)\right)\,\mathrm{d}y.
		\end{equation}

We show the equality by proving that the Laplace transforms with respect to $v$ of both sides are equal. Multiplying the left-hand side of \eqref{eq: proof LSTs same} by $e^{-\omega v}$, integrating $v$ over $(0,\infty)$ and changing the order of integration yields 
		\begin{align*}
			\int_0^\infty e^{-\alpha x} \left( \int_x^\infty e^{-\omega v}\,\mathrm{d}v\right)\mathrm{d}W^{(0)}_1(x) = \frac{1}{\omega}\int_0^\infty e^{-(\alpha+\omega) x} \mathrm{d} W^{(0)}_1(x).
		\end{align*}
		Integrating by parts then gives
		\begin{equation}\label{eq: proof LSTs same step 1}
			\frac{1}{\omega}\left(-W^{(0)}_1(0) + \frac{\alpha+\omega}{\varphi_1(\alpha+\omega)}\right).
		\end{equation}
		Multiplying the right-hand side of \eqref{eq: proof LSTs same} by $e^{-\omega v}$, integrating $v$ over $(0,\infty)$ and changing the order of integration yields for the first term
		\begin{equation}\label{eq: proof LSTs same step 2a}
			\frac{\lambda_1}{-r_1}\int_0^\infty e^{-\alpha y} \left( \int_y^\infty e^{-\omega v}\,\mathrm{d}v\right) W^{(0)}_1(y) \,\mathrm{d}y =\frac{\lambda_1}{-r_1\omega} \frac{1}{\varphi_1(\alpha + \omega)}.
		\end{equation}
		For the second, double integral, after applying the change in the order of integration $(\mathrm{d}x, \mathrm{d}y, \mathrm{d}v) \to (\mathrm{d}x, \mathrm{d}v, \mathrm{d}y)$, substituting $z:= v-y$, and then changing the order of integration to $(\mathrm{d}x, \mathrm{d}z, \mathrm{d}y) \to (\mathrm{d}z, \mathrm{d}x, \mathrm{d}y)$, we obtain
		\begin{align*}
			\frac{\lambda_1}{-r_1}\int_0^\infty e^{-(\alpha+\omega)y}W^{(0)}_1(y) \int_0^\infty e^{-\alpha x} \int_x^\infty e^{-\omega z}\,\mathrm{d}z\,\mathbb{P}(B_1\in\mathrm{d}x)\,\mathrm{d}y,
		\end{align*}
		which can be simplified to
		\begin{equation}\label{eq: proof LSTs same step 2b}
			\frac{\lambda_1}{-r_1\omega}\frac{\mathscr{B}_1(\alpha+\omega)}{\varphi_1(\alpha+\omega)}.
		\end{equation}
		Taking the difference of \eqref{eq: proof LSTs same step 2a} and \eqref{eq: proof LSTs same step 2b} gives for the Laplace transform of the right-hand side of \eqref{eq: proof LSTs same}
		\begin{align*}
			\frac{\lambda_1}{-r_1\omega} \frac{1-\mathscr{B}_1(\alpha+\omega)}{\varphi_1(\alpha+\omega)}.
		\end{align*}
		Using \eqref{eq: def laplace exp}, this can be rewritten to
		\begin{equation*}
			\frac{1}{\omega}\left(\frac{1}{r_1} + \frac{\alpha+\omega}{\varphi_1(\alpha+\omega)}\right).
		\end{equation*}
		Since $W_1^{(0)}(0) = -r_1^{-1}$ for a compound Poisson process with drift, this is equal to \eqref{eq: proof LSTs same step 1}, thus showing the equivalence of \eqref{eq: proof LSTs same}.

\label{coro: renewal equation}
		For $x\in[0,\infty)$,
		\begin{equation}\label{eq: renewal equation}
			W_1^{(0)}(x) = -\frac{1}{r_1} - \frac{\lambda_1}{r_1}\int_0^x W_1^{(0)}(y)\mathbb{P}(B_1>x-y)\,\mathrm{d}y.
		\end{equation}
